import { EgradxApiError } from '@babulvaibhav/egradx-client'

/*
 * Shared by the EGRADX recipes (shadcn registry items from @babulvaibhav/egradx-ui). Copied into your project like the rest of
 * a recipe: change the wording, the formats or the colours here and every recipe follows.
 */

/** Something to tell the person: wire it to your toasts (`sonner`'s `toast[tone](title, { description })`). */
export type Notify = (message: { tone: 'success' | 'info' | 'warning' | 'error'; title: string; description?: string }) => void

/** Used when a recipe is given no `onNotify`: messages are dropped, the screens still show errors inline. */
export const ignoreNotice: Notify = () => {}

/** Badge colours by meaning, for `<Badge variant="outline" className={tone.success}>`. */
export const tone = {
  success: 'border-emerald-500/30 bg-emerald-500/10 text-emerald-700 dark:text-emerald-400',
  warning: 'border-amber-500/30 bg-amber-500/10 text-amber-700 dark:text-amber-400',
  info: 'border-sky-500/30 bg-sky-500/10 text-sky-700 dark:text-sky-400',
  danger: 'border-destructive/30 bg-destructive/10 text-destructive',
  muted: 'text-muted-foreground',
} as const

const dateTime = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' })
const relative = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' })

export function formatDateTime(iso: string | null | undefined): string {
  return iso ? dateTime.format(new Date(iso)) : '—'
}

/** "3 minutes ago", "in 2 hours". */
export function formatRelative(iso: string | null | undefined): string {
  if (!iso) return '—'
  const seconds = (new Date(iso).getTime() - Date.now()) / 1000
  const units: [Intl.RelativeTimeFormatUnit, number][] = [['year', 31536000], ['month', 2592000], ['day', 86400], ['hour', 3600], ['minute', 60]]
  for (const [unit, size] of units) {
    if (Math.abs(seconds) >= size) return relative.format(Math.round(seconds / size), unit)
  }
  return relative.format(Math.round(seconds), 'second')
}

/** `oim.product_updated` → "Oim product updated". */
export function humanize(value: string | null | undefined): string {
  if (!value) return ''
  const words = value.replace(/[._-]+/g, ' ').trim().toLowerCase()
  return words.charAt(0).toUpperCase() + words.slice(1)
}

export function shortId(id: string): string {
  return id.slice(0, 8)
}

/** A channel id as people read it. Unknown ids, added by configuration, are shown as they are. */
export function channelLabel(id: string): string {
  const labels: Record<string, string> = { email: 'Email', sms: 'SMS', whatsapp: 'WhatsApp', slack: 'Slack', webhook: 'Webhook', log: 'Log' }
  return labels[id] ?? id
}

/** What went wrong, to show the person: the server's message, or a plain one. */
export function errorText(error: unknown): string {
  if (error instanceof EgradxApiError) {
    if (error.code === 'NETWORK_ERROR') return 'The server could not be reached. Check your connection and try again.'
    if (error.code === 'ACCESS_DENIED') return 'You do not have permission to do this.'
    return error.message
  }
  return error instanceof Error ? error.message : 'Something went wrong.'
}

export function errorCode(error: unknown): string | undefined {
  return error instanceof EgradxApiError ? error.code : undefined
}

'use client'

import { useEffect, useState, type ReactNode } from 'react'
import { Inbox, LoaderCircle, RefreshCw, Search, ShieldAlert, TriangleAlert, X } from 'lucide-react'
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'
import { errorCode, errorText } from './egradx-ui'

/* The small pieces every EGRADX recipe shares: empty and error states, a confirmation, a search box. */

interface StateProps {
  icon?: ReactNode
  title: ReactNode
  description?: ReactNode
  action?: ReactNode
  className?: string
}

export function EmptyState({ icon = <Inbox />, title, description, action, className }: StateProps) {
  return (
    <div className={cn('flex flex-col items-center justify-center gap-3 px-6 py-12 text-center', className)}>
      <div className="bg-muted text-muted-foreground flex size-12 items-center justify-center rounded-full [&_svg]:size-5">{icon}</div>
      <div className="space-y-1">
        <p className="font-medium">{title}</p>
        {description && <p className="text-muted-foreground mx-auto max-w-sm text-sm">{description}</p>}
      </div>
      {action}
    </div>
  )
}

/** A failed load: "not allowed" for a refusal, otherwise what went wrong, with a retry. */
export function ErrorState({ error, onRetry, className }: { error: unknown; onRetry?: () => void; className?: string }) {
  if (errorCode(error) === 'ACCESS_DENIED') {
    return (
      <EmptyState
        className={className}
        icon={<ShieldAlert />}
        title="Access restricted"
        description="Your role does not include this. Ask an administrator if you need it."
      />
    )
  }
  return (
    <EmptyState
      className={className}
      icon={<TriangleAlert className="text-destructive" />}
      title="Couldn't load this"
      description={errorText(error)}
      action={
        onRetry && (
          <Button variant="outline" size="sm" onClick={onRetry}>
            <RefreshCw /> Try again
          </Button>
        )
      }
    />
  )
}

interface ConfirmDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: ReactNode
  description?: ReactNode
  confirmLabel?: string
  destructive?: boolean
  pending?: boolean
  onConfirm: () => void
}

/** Asks before something that cannot be undone; stays open until the change is done. */
export function ConfirmDialog({ open, onOpenChange, title, description, confirmLabel = 'Confirm', destructive, pending, onConfirm }: ConfirmDialogProps) {
  return (
    <AlertDialog open={open} onOpenChange={(next) => !pending && onOpenChange(next)}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          {description && <AlertDialogDescription>{description}</AlertDialogDescription>}
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending}>Cancel</AlertDialogCancel>
          <Button variant={destructive ? 'destructive' : 'default'} disabled={pending} onClick={onConfirm}>
            {pending && <LoaderCircle className="animate-spin" />}
            {confirmLabel}
          </Button>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

/** A search box that reports what was typed once typing pauses. */
export function SearchBox({ value, onChange, placeholder = 'Search…', className }: { value: string; onChange: (value: string) => void; placeholder?: string; className?: string }) {
  const [draft, setDraft] = useState(value)
  useEffect(() => setDraft(value), [value])
  useEffect(() => {
    if (draft.trim() === value) return
    const timer = setTimeout(() => onChange(draft.trim()), 300)
    return () => clearTimeout(timer)
    // Only typing starts the timer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draft])
  return (
    <div className={cn('relative w-full sm:w-72', className)}>
      <Search className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2" />
      <Input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder={placeholder} aria-label={placeholder} className="pr-8 pl-9" />
      {draft && (
        <button
          type="button"
          onClick={() => setDraft('')}
          className="text-muted-foreground hover:text-foreground absolute top-1/2 right-2 -translate-y-1/2 rounded p-0.5"
          aria-label="Clear search"
        >
          <X className="size-3.5" />
        </button>
      )}
    </div>
  )
}

import { acceptList } from '@babulvaibhav/egradx-client'
import { errorCode, errorText } from '../egradx-ui'

/* The files recipes' wording and formats. Change them here and the upload, attachments and avatar recipes follow. */

const sizeFormat = new Intl.NumberFormat(undefined, { maximumFractionDigits: 1 })

/** 1536 → "1.5 KB". */
export function formatFileSize(bytes: number | null | undefined): string {
  if (bytes === null || bytes === undefined) return '—'
  const units = ['bytes', 'KB', 'MB', 'GB']
  let value = bytes
  let unit = 0
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024
    unit += 1
  }
  return unit === 0 ? `${bytes} ${bytes === 1 ? 'byte' : 'bytes'}` : `${sizeFormat.format(value)} ${units[unit]}`
}

const FAMILIES: Record<string, string> = { 'image/*': 'images', 'video/*': 'videos', 'audio/*': 'audio', 'text/*': 'text files' }
const TYPES: Record<string, string> = {
  'application/pdf': 'PDF',
  'image/png': 'PNG',
  'image/jpeg': 'JPEG',
  'image/webp': 'WebP',
  'image/gif': 'GIF',
  'text/csv': 'CSV',
  'application/zip': 'ZIP',
}

/** `image/*, application/pdf` → "images or PDF". */
export function describeAccept(accept: string | readonly string[] | undefined): string {
  const names = acceptList(accept).map((rule) => FAMILIES[rule] ?? TYPES[rule] ?? (rule.startsWith('.') ? rule.slice(1).toUpperCase() : rule))
  const unique = [...new Set(names)]
  return unique.length <= 1 ? (unique[0] ?? '') : `${unique.slice(0, -1).join(', ')} or ${unique.at(-1)}`
}

/** Limits a screen shows and checks: what it accepts, and the largest size. */
export interface FileLimitsText {
  accept?: string | readonly string[]
  maxSize?: number
}

/** "PDF or images, up to 25 MB." — or nothing, when there are no limits to tell. */
export function limitsHint({ accept, maxSize }: FileLimitsText): string {
  const parts = [describeAccept(accept), maxSize ? `up to ${formatFileSize(maxSize)}` : ''].filter(Boolean)
  if (!parts.length) return ''
  const text = parts.join(', ')
  return `${text.charAt(0).toUpperCase()}${text.slice(1)}.`
}

/** What went wrong with a file, worded per code. The limits are the screen's, used when the refusal carries none. */
export function fileErrorText(error: unknown, limits: FileLimitsText = {}): string {
  const details = (error as { details?: { maxSize?: number } } | null)?.details
  switch (errorCode(error)) {
    case 'FILE_TOO_LARGE': {
      const max = details?.maxSize ?? limits.maxSize
      return max ? `The file is larger than ${formatFileSize(max)}.` : 'The file is too large.'
    }
    case 'FILE_TYPE_NOT_ALLOWED': {
      const allowed = describeAccept(limits.accept)
      return allowed ? `This type of file isn't allowed. Choose ${allowed}.` : "This type of file isn't allowed here."
    }
    case 'FILE_EMPTY':
      return 'The file is empty.'
    case 'FILE_REJECTED':
      return 'The file was refused by a safety check.'
    case 'FILE_STORAGE_UNAVAILABLE':
      return "Files can't be stored right now. Try again in a moment."
    case 'NOT_FOUND':
      return 'The file no longer exists.'
    case 'ACCESS_DENIED':
      return "You don't have permission to do this."
    default:
      return errorText(error)
  }
}

/** Two letters for an avatar without a photo: "Ada Lovelace" → "AL". */
export function initialsOf(name: string | null | undefined): string {
  const words = (name ?? '').trim().split(/[\s@._-]+/).filter(Boolean)
  return ((words[0]?.[0] ?? '') + (words.length > 1 ? (words.at(-1)?.[0] ?? '') : '')).toUpperCase() || '?'
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { Camera, LoaderCircle, Trash2 } from 'lucide-react'
import { useProfilePhoto } from '@babulvaibhav/egradx-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import { ConfirmDialog } from '../egradx-common'
import { ignoreNotice, type Notify } from '../egradx-ui'
import { fileErrorText, initialsOf, limitsHint } from './file-format'

const PHOTO_TYPES = 'image/png,image/jpeg,image/webp'
const PHOTO_MAX = 5 * 1024 * 1024

export interface ProfilePhotoProps {
  /** The person's name, for the initials shown without a photo. */
  name?: string | null
  className?: string
  /** Classes for the initials. */
  fallbackClassName?: string
}

/**
 * The signed-in person's photo, or their initials: for a header or a menu. It changes as soon as the photo is changed
 * anywhere in the app.
 */
export function ProfilePhoto({ name, className, fallbackClassName }: ProfilePhotoProps) {
  const photo = useProfilePhoto()
  // The URL that failed to load, so that a new one is tried again.
  const [failed, setFailed] = useState<string>()
  return (
    <span className={cn('bg-muted relative flex size-8 shrink-0 items-center justify-center overflow-hidden rounded-full', className)}>
      {photo.url && photo.url !== failed ? (
        <img src={photo.url} alt="" className="size-full object-cover" onError={() => setFailed(photo.url)} />
      ) : (
        <span className={cn('text-xs font-semibold', fallbackClassName)} aria-hidden>
          {initialsOf(name)}
        </span>
      )}
    </span>
  )
}

export interface AvatarUploadProps {
  /** The person's name, for the initials shown without a photo. */
  name?: string | null
  /** As the server's `egradx.files.profile-photo.content-types`. Default PNG, JPEG and WebP. */
  accept?: string
  /** As the server's `egradx.files.profile-photo.max-size`. Default 5 MB. */
  maxSize?: number
  onNotify?: Notify
  className?: string
}

/** The signed-in person's profile photo: a preview, choosing or dropping a new one, and removing it. */
export function AvatarUpload({ name, accept = PHOTO_TYPES, maxSize = PHOTO_MAX, onNotify = ignoreNotice, className }: AvatarUploadProps) {
  const photo = useProfilePhoto({ accept, maxSize })
  const input = useRef<HTMLInputElement>(null)
  const [preview, setPreview] = useState<string | null>(null)
  const [confirming, setConfirming] = useState(false)
  const [dragging, setDragging] = useState(false)

  // The chosen file is shown at once, while it uploads; its object URL goes when it is no longer shown.
  useEffect(() => () => {
    if (preview) URL.revokeObjectURL(preview)
  }, [preview])

  async function choose(file: File | undefined) {
    if (!file) return
    photo.resetError()
    setPreview(URL.createObjectURL(file))
    try {
      await photo.set(file)
      onNotify({ tone: 'success', title: 'Profile photo updated' })
    } catch {
      // The reason is shown below.
    } finally {
      setPreview(null)
    }
  }

  async function remove() {
    try {
      await photo.remove()
      setConfirming(false)
      onNotify({ tone: 'success', title: 'Profile photo removed' })
    } catch {
      setConfirming(false)
    }
  }

  const shown = preview ?? photo.url
  const percent = Math.round((photo.progress?.fraction ?? 0) * 100)

  return (
    <div className={cn('flex flex-wrap items-center gap-4', className)}>
      <button
        type="button"
        onClick={() => input.current?.click()}
        onDragOver={(event) => {
          event.preventDefault()
          setDragging(true)
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(event) => {
          event.preventDefault()
          setDragging(false)
          void choose(event.dataTransfer.files[0])
        }}
        disabled={photo.uploading}
        aria-label={photo.url ? 'Change your photo' : 'Add a photo'}
        className={cn(
          'group bg-muted relative flex size-20 shrink-0 items-center justify-center overflow-hidden rounded-full outline-offset-2',
          dragging && 'ring-primary ring-2',
        )}
      >
        {shown ? (
          <img src={shown} alt="" className="size-full object-cover" />
        ) : photo.loading ? (
          <LoaderCircle className="text-muted-foreground size-5 animate-spin" />
        ) : (
          <span className="text-muted-foreground text-xl font-semibold">{initialsOf(name)}</span>
        )}
        <span
          className={cn(
            'absolute inset-0 flex items-center justify-center bg-black/45 text-xs font-medium text-white transition-opacity',
            photo.uploading ? 'opacity-100' : 'opacity-0 group-hover:opacity-100 group-focus-visible:opacity-100',
          )}
        >
          {photo.uploading ? `${percent}%` : <Camera className="size-5" />}
        </span>
      </button>
      <div className="min-w-0 space-y-2">
        <div className="flex flex-wrap gap-2">
          <Button type="button" size="sm" variant="outline" disabled={photo.uploading} onClick={() => input.current?.click()}>
            {photo.uploading ? <LoaderCircle className="animate-spin" /> : <Camera />}
            {photo.url ? 'Change photo' : 'Upload photo'}
          </Button>
          {photo.url && !photo.uploading && (
            <Button type="button" size="sm" variant="ghost" onClick={() => setConfirming(true)}>
              <Trash2 /> Remove
            </Button>
          )}
        </div>
        <p className="text-muted-foreground text-xs">{limitsHint({ accept, maxSize })}</p>
        {photo.changeError && (
          <p role="alert" className="text-destructive text-sm">
            {fileErrorText(photo.changeError, { accept, maxSize })}
          </p>
        )}
      </div>
      <input
        ref={input}
        type="file"
        accept={accept}
        className="sr-only"
        tabIndex={-1}
        onChange={(event) => {
          const file = event.target.files?.[0]
          event.target.value = ''
          void choose(file)
        }}
      />
      <ConfirmDialog
        open={confirming}
        onOpenChange={setConfirming}
        title="Remove your photo?"
        description="Your initials are shown instead."
        confirmLabel="Remove"
        destructive
        pending={photo.removing}
        onConfirm={() => void remove()}
      />
    </div>
  )
}
